H.background();
H.text("Bohr model: En = -13.6 / n^2 eV", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
const n = Math.max(1, Math.min(5, Math.round(P.n)));
const RY = 13.6;
const En = -RY / (n * n);
H.text("current level n=" + n + "    En = " + En.toFixed(2) + " eV    radius ~ n^2 a0", 24, 52, { color: H.colors.sub, size: 13 });
const cx = 280, cy = 300;
H.circle(cx, cy, 12, { fill: H.colors.warn, stroke: H.colors.ink, width: 1 });
H.text("+", cx - 4, cy + 5, { color: H.colors.bg, size: 16, weight: 700 });
const rMax = 230;
for (let k = 1; k <= 5; k++) {
  const r = rMax * (k * k) / 25;
  const on = k === n;
  H.circle(cx, cy, r, { stroke: on ? H.colors.accent : H.colors.grid, width: on ? 2.5 : 1 });
  H.text("n=" + k, cx + r - 10, cy - 6, { color: on ? H.colors.ink : H.colors.sub, size: 11 });
}
const rn = rMax * (n * n) / 25;
const ang = t * (3 / n);
const ex = cx + rn * Math.cos(ang);
const ey = cy + rn * Math.sin(ang);
H.circle(ex, ey, 7, { fill: H.colors.yellow, stroke: H.colors.ink, width: 1 });
const lx = 640, lyTop = 110, lyBot = H.H - 70;
H.text("energy (eV)", lx, 92, { color: H.colors.sub, size: 12 });
for (let k = 1; k <= 5; k++) {
  const Ek = -RY / (k * k);
  const y = H.map(Ek, -RY, 0, lyBot, lyTop);
  const on = k === n;
  H.line(lx, y, lx + 170, y, { color: on ? H.colors.accent : H.colors.grid, width: on ? 2.5 : 1 });
  H.text(Ek.toFixed(2), lx + 176, y + 4, { color: on ? H.colors.ink : H.colors.sub, size: 11 });
}
H.line(lx, lyTop - 6, lx, lyBot, { color: H.colors.axis, width: 1 });
H.text("n=infinity, E=0 (ionized)", lx, lyTop - 2, { color: H.colors.sub, size: 10 });
const ay = H.map(En, -RY, 0, lyBot, lyTop);
H.circle(lx + 85 + 4 * Math.sin(t * 2), ay, 6, { fill: H.colors.yellow });
H.text("E" + n + " = " + En.toFixed(2) + " eV", 24, H.H - 24, { color: H.colors.good, size: 13 });
